<script nonce="{{ csrf_token() }}">function requestLineForModel(id){var q=parseInt($('#model-booking-quantity-'+id).val(),10),d=parseInt($('#model-booking-discipline-'+id).val(),10),c=parseInt($('#model-booking-company-'+id).val(),10);if(!q||!d||!c){window.alert('Enter a total needed quantity, discipline, and destination site for each model.');return null}return{model_id:id,quantity:q,discipline_id:d,company_id:c}}$(document).on('click','.add-model-to-request-cart',function(){var l=requestLineForModel(+$(this).data('model-id'));if(l)addLinesToRequestCart([l],false)});$(function(){var $t=$('#requestableModelsTable'),active={};if(!$t.length)return;function apply(){$t.bootstrapTable('filterBy',{}, {filterAlgorithm:function(r){return Object.keys(active).every(function(k){var f=active[k],v=String(r[k]||'').toLowerCase();if(f.op){var n=parseFloat(v);return {'=':n===f.n,'>=':n>=f.n,'<=':n<=f.n}[f.op]}return v.indexOf(f.v.toLowerCase())>=0})}});var d=$('#appliedSpecFilters').empty();Object.keys(active).forEach(function(k){d.append($('<button class="btn btn-default btn-xs" style="margin-right:4px"></button>').text(active[k].label+': '+(active[k].op||'')+(active[k].v||active[k].n)+' ×').click(function(){$('.spec-filter[data-field="'+k+'"]').val('');delete active[k];apply()}))});$('#clearSpecFilters').prop('hidden',!Object.keys(active).length);$('#modelCount').text($t.bootstrapTable('getData').length+' matching models')}$('.spec-filter').on('input change',function(){var x=$(this),v=x.val(),k=x.data('field');if(!v)delete active[k];else active[k]={label:x.data('label'),v:v,n:+v,op:x.is('[type=number]')?$('.spec-operator[data-field="'+k+'"]').val():null};apply()});$('#clearSpecFilters').click(function(){$('.spec-filter').val('');active={};apply()});$('.fixed-table-toolbar .search input').attr('placeholder','Search models or technical specifications');apply()})</script>
